import math

def tau(n):
    if n == 1:
        return 1
    count = 0
    d = 1
    while d * d <= n:
        if n % d == 0:
            if d * d == n:
                count += 1
            else:
                count += 2
        d += 1
    return count

def is_exotic_count(k):
    # k is exotic if k = 2 * odd integer
    return k % 2 == 0 and (k // 2) % 2 == 1

exotic_integers = []
n = 1
while len(exotic_integers) < 10:
    t = tau(n)
    if is_exotic_count(t):
        exotic_integers.append(n)
    n += 1

print("First 10 exotic integers:", exotic_integers)

